22	/** Lists all active share links for a memo (creator-only). */
23	export function useMemoShares(memoName: string, options?: { enabled?: boolean }) {
24	  return useQuery({
25	    queryKey: memoShareKeys.list(memoName),
26	    queryFn: async () => {
27	      const response = await memoServiceClient.listMemoShares(create(ListMemoSharesRequestSchema, { parent: memoName }));
28	      return response.memoShares;
29	    },
30	    enabled: options?.enabled ?? !!memoName,
31	  });
32	}
