95	/** Rewrites attachment URLs to include a share token for unauthenticated access. */
96	export function withShareAttachmentLinks(attachments: Attachment[], token: string): Attachment[] {
97	  return attachments.map((a) => {
98	    if (a.externalLink) return a;
99	    return { ...a, externalLink: `${window.location.origin}/file/${a.name}/${a.filename}?share_token=${encodeURIComponent(token)}` };
100	  });
